// In-browser backend for the static (GitHub Pages) build.
// Mirrors the Node API routes so pages don't know the difference. Catalogue comes from
// data/catalog.json (generated by `npm run build:static`); bag, wishlist, demo accounts and
// orders live in this browser's localStorage. Nothing is sent anywhere.

const FREE_SHIPPING_FROM = 1499;
const SHIPPING_FEE = 99;
const COUPONS = {
  VASTRA10: { label: '10% off your order', apply: (sub) => Math.round(sub * 0.1) },
  FIRST200: { label: '₹200 off orders above ₹1,999', apply: (sub) => (sub >= 1999 ? 200 : 0), min: 1999 },
};
const STAGES = [
  { key: 'placed', label: 'Order placed', after: 0 },
  { key: 'confirmed', label: 'Confirmed', after: 60 * 1000 },
  { key: 'packed', label: 'Packed with care', after: 30 * 60 * 1000 },
  { key: 'shipped', label: 'Shipped', after: 6 * 3600 * 1000 },
  { key: 'out', label: 'Out for delivery', after: 2 * 86400 * 1000 },
  { key: 'delivered', label: 'Delivered', after: 3 * 86400 * 1000 },
];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE = /^[6-9]\d{9}$/;
const PIN = /^\d{6}$/;

class HttpError extends Error { constructor(status, message) { super(message); this.status = status; } }
const fail = (status, message) => { throw new HttpError(status, message); };

// ---------- storage ----------
const mem = {};
const load = (k, d) => { try { const v = localStorage.getItem(`jv_${k}`); return v ? JSON.parse(v) : d; } catch { return mem[k] ?? d; } };
const save = (k, v) => { mem[k] = v; try { localStorage.setItem(`jv_${k}`, JSON.stringify(v)); } catch { /* private mode: memory only */ } };

let data = null;
async function catalogData() {
  if (!data) {
    const res = await fetch(new URL('data/catalog.json', document.baseURI));
    data = await res.json();
    const delta = load('stock_delta', {});
    data.products.forEach((p) => {
      Object.entries(delta[p.id] || {}).forEach(([s, d]) => { p.stock[s] = Math.max(0, (p.stock[s] || 0) + d); });
      p.inStock = Object.values(p.stock).some((n) => n > 0);
    });
  }
  return data;
}
function adjustStock(p, size, d) {
  const delta = load('stock_delta', {});
  delta[p.id] = delta[p.id] || {};
  delta[p.id][size] = (delta[p.id][size] || 0) + d;
  save('stock_delta', delta);
  p.stock[size] = Math.max(0, (p.stock[size] || 0) + d);
  p.inStock = Object.values(p.stock).some((n) => n > 0);
}

// ---------- identity ----------
const session = () => load('session', null);
const users = () => load('users', {});
const currentUser = () => { const s = session(); const u = s && users()[s]; return u ? publicUser(u) : null; };
const publicUser = (u) => ({ id: u.id, name: u.name, email: u.email, phone: u.phone || null, created_at: u.created_at });
const owner = () => { const u = currentUser(); return u ? `u:${u.id}` : 'guest'; };
const bags = () => load('bags', {});
const wishes = () => load('wishes', {});

async function hash(password, salt) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: new TextEncoder().encode(salt), iterations: 120000 }, key, 256);
  return [...new Uint8Array(bits)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

function mergeGuest(uid) {
  const b = bags(); const w = wishes(); const to = `u:${uid}`;
  (b.guest || []).forEach((i) => {
    const ex = (b[to] = b[to] || []).find((x) => x.productId === i.productId && x.size === i.size);
    if (ex) ex.qty = Math.min(10, ex.qty + i.qty); else b[to].push(i);
  });
  w[to] = [...new Set([...(w.guest || []), ...(w[to] || [])])];
  delete b.guest; delete w.guest;
  save('bags', b); save('wishes', w);
}

// ---------- cart ----------
async function cartFor(coupon) {
  const { products } = await catalogData();
  const rows = bags()[owner()] || [];
  const items = rows.map((r) => {
    const p = products.find((x) => x.id === r.productId);
    if (!p) return null;
    return { productId: p.id, slug: p.slug, name: p.name, image: p.images[0], color: p.color, size: r.size, qty: r.qty, price: p.price, mrp: p.mrp, lineTotal: p.price * r.qty, available: p.stock[r.size] || 0 };
  }).filter(Boolean);
  const subtotal = items.reduce((a, i) => a + i.lineTotal, 0);
  const mrpTotal = items.reduce((a, i) => a + i.mrp * i.qty, 0);
  const code = coupon && COUPONS[String(coupon).toUpperCase()] ? String(coupon).toUpperCase() : null;
  const discount = code ? COUPONS[code].apply(subtotal) : 0;
  const shipping = subtotal === 0 || subtotal - discount >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;
  return { items, count: items.reduce((a, i) => a + i.qty, 0), subtotal, savings: mrpTotal - subtotal, coupon: code, couponLabel: code ? COUPONS[code].label : null, discount, shipping, total: subtotal - discount + shipping, freeShippingFrom: FREE_SHIPPING_FROM };
}
function setBag(rows) { const b = bags(); b[owner()] = rows; save('bags', b); }

// ---------- orders ----------
function withTracking(o) {
  const elapsed = Date.now() - o.createdAt;
  const timeline = o.status === 'cancelled'
    ? [{ key: 'placed', label: 'Order placed', at: o.createdAt, done: true }, { key: 'cancelled', label: 'Cancelled', done: true }]
    : STAGES.map((s) => ({ key: s.key, label: s.label, at: o.createdAt + s.after, done: elapsed >= s.after }));
  const status = o.status === 'cancelled' ? 'cancelled' : [...timeline].reverse().find((s) => s.done).key;
  return { ...o, status, timeline, estimatedDelivery: o.createdAt + 4 * 86400000, cancellable: o.status !== 'cancelled' && elapsed < STAGES[3].after };
}
const allOrders = () => load('orders', []);
const requireUser = () => currentUser() || fail(401, 'Please sign in to continue.');

// ---------- router ----------
export async function handle(method, url, body = {}) {
  const u = new URL(url, 'http://x');
  const path = u.pathname; const q = Object.fromEntries(u.searchParams);
  const { products, categories } = await catalogData();
  const route = `${method} ${path}`;
  let m;

  if (route === 'GET /categories') return categories;

  if (route === 'GET /products') {
    let list = [...products];
    if (q.category && q.category !== 'all') list = list.filter((p) => p.category === q.category);
    if (q.tag) list = list.filter((p) => p.tags.includes(q.tag));
    if (q.q) {
      const terms = q.q.toLowerCase().split(/\s+/).filter(Boolean);
      list = list.filter((p) => { const hay = `${p.name} ${p.categoryName} ${p.color} ${p.fabric} ${p.description} ${p.garment}`.toLowerCase(); return terms.every((t) => hay.includes(t) || hay.includes(t.replace(/s$/, ''))); });
    }
    const scoped = list;
    if (q.colors) { const set = q.colors.split(','); list = list.filter((p) => set.includes(p.color)); }
    if (q.sizes) { const set = q.sizes.split(','); list = list.filter((p) => set.some((s) => (p.stock[s] || 0) > 0)); }
    if (q.min) list = list.filter((p) => p.price >= Number(q.min));
    if (q.max) list = list.filter((p) => p.price <= Number(q.max));
    if (q.availability === 'in') list = list.filter((p) => p.inStock);
    const sorters = { popular: (a, b) => b.popularity - a.popularity, newest: (a, b) => b.createdAt.localeCompare(a.createdAt), 'price-asc': (a, b) => a.price - b.price, 'price-desc': (a, b) => b.price - a.price, discount: (a, b) => b.discount - a.discount };
    list.sort(sorters[q.sort] || sorters.popular);
    const count = (arr, fn) => arr.reduce((acc, p) => { fn(p).forEach((k) => { acc[k] = (acc[k] || 0) + 1; }); return acc; }, {});
    return { total: list.length, products: list, facets: { colors: count(scoped, (p) => [p.color]), sizes: count(scoped, (p) => p.sizes), price: { min: Math.min(...products.map((p) => p.price)), max: Math.max(...products.map((p) => p.price)) } } };
  }
  if ((m = /^GET \/products\/([a-z0-9-]+)$/.exec(route))) {
    const product = products.find((p) => p.slug === m[1]) || fail(404, 'Product not found');
    const related = products.filter((p) => p.slug !== product.slug && (p.category === product.category || p.color === product.color))
      .sort((a, b) => (b.category === product.category) - (a.category === product.category) || b.popularity - a.popularity).slice(0, 8);
    return { product, related };
  }
  if (route === 'GET /search/suggest') {
    const t = (q.q || '').toLowerCase().trim();
    if (!t) return [];
    return products.filter((p) => `${p.name} ${p.color} ${p.categoryName}`.toLowerCase().includes(t)).slice(0, 6)
      .map((p) => ({ slug: p.slug, name: p.name, price: p.price, image: p.images[0], category: p.categoryName }));
  }
  if (route === 'GET /tryon/config') return { cloud: false, providers: [], sareeSupported: false, local: true, static: true };
  if (route === 'POST /tryon') fail(503, 'Photoreal cloud try-on needs the Node server. Use the instant on-device mode on this preview.');

  // cart
  if (route === 'GET /cart') return cartFor(q.coupon);
  if (route === 'POST /cart') {
    const p = products.find((x) => x.id === Number(body.productId)) || fail(404, 'Product not found');
    if (!p.sizes.includes(body.size)) fail(400, 'Please choose a size');
    const rows = bags()[owner()] || [];
    const ex = rows.find((r) => r.productId === p.id && r.size === body.size);
    const next = Math.min((ex ? ex.qty : 0) + Math.max(1, Number(body.qty) || 1), 10, p.stock[body.size] || 0);
    if (next < 1) fail(409, `Size ${body.size} is sold out`);
    if (ex) ex.qty = next; else rows.push({ productId: p.id, size: body.size, qty: next });
    setBag(rows); return cartFor();
  }
  if (route === 'PATCH /cart' || route === 'DELETE /cart') {
    const p = products.find((x) => x.id === Number(body.productId)) || fail(404, 'Product not found');
    let rows = bags()[owner()] || [];
    const n = method === 'DELETE' ? 0 : Math.min(Number(body.qty) || 0, 10, p.stock[body.size] || 0);
    if (n <= 0) rows = rows.filter((r) => !(r.productId === p.id && r.size === body.size));
    else rows.forEach((r) => { if (r.productId === p.id && r.size === body.size) r.qty = n; });
    setBag(rows); return cartFor(body.coupon);
  }
  if (route === 'POST /cart/coupon') {
    const code = String(body.code || '').toUpperCase();
    const c = COUPONS[code] || fail(400, 'That code is not valid');
    const cart = await cartFor(code);
    if (c.min && cart.subtotal < c.min) fail(400, `Add items worth ₹${c.min - cart.subtotal} more to use ${code}`);
    return cart;
  }

  // wishlist
  if (route === 'GET /wishlist') { const ids = wishes()[owner()] || []; return { ids, products: ids.map((id) => products.find((p) => p.id === id)).filter(Boolean) }; }
  if ((m = /^POST \/wishlist\/(\d+)$/.exec(route))) {
    const w = wishes(); const id = Number(m[1]); const list = w[owner()] || [];
    const has = list.includes(id);
    w[owner()] = has ? list.filter((x) => x !== id) : [id, ...list];
    save('wishes', w); return { saved: !has, ids: w[owner()] };
  }

  // account
  if (route === 'GET /account/me') return { user: currentUser() };
  if (route === 'POST /account/register') {
    const { name, email, phone, password } = body;
    if (!name || name.trim().length < 2) fail(400, 'Please enter your name');
    if (!EMAIL.test(email || '')) fail(400, 'Please enter a valid email');
    if (phone && !PHONE.test(phone)) fail(400, 'Please enter a valid 10-digit mobile number');
    if (!password || password.length < 8) fail(400, 'Password must be at least 8 characters');
    const all = users(); const key = email.toLowerCase().trim();
    if (all[key]) fail(409, 'An account with this email already exists');
    const salt = crypto.getRandomValues(new Uint32Array(4)).join('-');
    all[key] = { id: Date.now(), name: name.trim(), email: key, phone: phone || null, salt, hash: await hash(password, salt), created_at: new Date().toISOString().slice(0, 19).replace('T', ' ') };
    save('users', all); mergeGuest(all[key].id); save('session', key);
    return { user: publicUser(all[key]) };
  }
  if (route === 'POST /account/login') {
    const all = users(); const usr = all[String(body.email || '').toLowerCase().trim()];
    if (!usr || (await hash(body.password || '', usr.salt)) !== usr.hash) fail(401, 'Incorrect email or password');
    mergeGuest(usr.id); save('session', usr.email);
    return { user: publicUser(usr) };
  }
  if (route === 'POST /account/logout') { save('session', null); return { ok: true }; }
  if (route === 'PATCH /account/me') {
    const me = requireUser(); const all = users();
    if (!body.name || body.name.trim().length < 2) fail(400, 'Please enter your name');
    if (body.phone && !PHONE.test(body.phone)) fail(400, 'Please enter a valid 10-digit mobile number');
    Object.assign(all[me.email], { name: body.name.trim(), phone: body.phone || null }); save('users', all);
    return { user: publicUser(all[me.email]) };
  }
  if (route === 'POST /account/me/password') {
    const me = requireUser(); const all = users(); const rec = all[me.email];
    if ((await hash(body.current || '', rec.salt)) !== rec.hash) fail(400, 'Current password is incorrect');
    if (!body.next || body.next.length < 8) fail(400, 'New password must be at least 8 characters');
    rec.hash = await hash(body.next, rec.salt); save('users', all); return { ok: true };
  }

  // addresses
  const addrKey = () => `addr_${requireUser().id}`;
  const listAddr = () => load(addrKey(), []).sort((a, b) => b.is_default - a.is_default || b.id - a.id);
  const validAddr = (a) => {
    if (!a.name || !a.line1 || !a.city || !a.state) fail(400, 'Please fill in all required address fields');
    if (!PHONE.test(a.phone || '')) fail(400, 'Please enter a valid 10-digit mobile number');
    if (!PIN.test(a.pincode || '')) fail(400, 'Please enter a valid 6-digit PIN code');
  };
  if (route === 'GET /account/addresses') return listAddr();
  if (route === 'POST /account/addresses') {
    validAddr(body); let list = listAddr(); const first = !list.length;
    if (body.is_default) list = list.map((a) => ({ ...a, is_default: 0 }));
    const id = Date.now();
    list.push({ id, label: body.label || 'Home', name: body.name, phone: body.phone, line1: body.line1, line2: body.line2 || '', city: body.city, state: body.state, pincode: body.pincode, is_default: first || body.is_default ? 1 : 0 });
    save(addrKey(), list); return { id, addresses: listAddr() };
  }
  if ((m = /^(PUT|DELETE) \/account\/addresses\/(\d+)$/.exec(route))) {
    let list = listAddr(); const id = Number(m[2]);
    if (method === 'PUT') {
      validAddr(body);
      if (body.is_default) list = list.map((a) => ({ ...a, is_default: 0 }));
      list = list.map((a) => (a.id === id ? { ...a, label: body.label || 'Home', name: body.name, phone: body.phone, line1: body.line1, line2: body.line2 || '', city: body.city, state: body.state, pincode: body.pincode, is_default: body.is_default ? 1 : a.is_default } : a));
    } else {
      list = list.filter((a) => a.id !== id);
      if (list.length && !list.some((a) => a.is_default)) list[0].is_default = 1;
    }
    save(addrKey(), list); return listAddr();
  }

  // checkout & orders
  if (route === 'POST /checkout') {
    const me = requireUser();
    if (!['cod', 'upi', 'card'].includes(body.paymentMethod)) fail(400, 'Choose a payment method');
    const address = listAddr().find((a) => a.id === Number(body.addressId)) || fail(400, 'Choose a delivery address');
    const cart = await cartFor(body.coupon);
    if (!cart.items.length) fail(400, 'Your bag is empty');
    const short = cart.items.find((i) => i.qty > i.available);
    if (short) fail(409, `Only ${short.available} left of ${short.name} (${short.size}). Please update your bag.`);
    cart.items.forEach((i) => adjustStock(products.find((p) => p.id === i.productId), i.size, -i.qty));
    const { id: _i, is_default: _d, ...addr } = address;
    const order = {
      id: Date.now(), number: `JV${String(Date.now()).slice(-6)}${100 + Math.floor(Math.random() * 900)}`, userId: me.id,
      items: cart.items.map(({ productId, slug, name, image, color, size, qty, price }) => ({ productId, slug, name, image, color, size, qty, price })),
      subtotal: cart.subtotal, discount: cart.discount, shipping: cart.shipping, total: cart.total, coupon: cart.coupon,
      address: addr, paymentMethod: body.paymentMethod, status: 'placed', createdAt: Date.now(),
    };
    save('orders', [order, ...allOrders()]); setBag([]);
    return withTracking(order);
  }
  if (route === 'GET /orders') { const me = requireUser(); return allOrders().filter((o) => o.userId === me.id).map(withTracking); }
  if ((m = /^(GET|POST) \/orders\/([A-Z0-9]+)(\/cancel)?$/.exec(route))) {
    const me = requireUser(); const orders = allOrders();
    const o = orders.find((x) => x.number === m[2] && x.userId === me.id) || fail(404, 'Order not found');
    if (m[3]) {
      if (!withTracking(o).cancellable) fail(409, 'This order has already shipped and can no longer be cancelled.');
      o.items.forEach((i) => adjustStock(products.find((p) => p.id === i.productId), i.size, i.qty));
      o.status = 'cancelled'; save('orders', orders);
    }
    return withTracking(o);
  }
  fail(404, 'Not found');
}
